package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1000000007

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var k int
	var w int64
	fmt.Fscan(in, &k, &w)

	fall := make([]int64, k+1)
	invFall := make([]int64, k+1)

	fall[0] = 1
	for d := 1; d <= k; d++ {
		fall[d] = fall[d-1] * int64(k-d+1) % mod
	}

	invFall[k] = modPow(fall[k], mod-2)
	for d := k; d >= 1; d-- {
		invFall[d-1] = invFall[d] * int64(k-d+1) % mod
	}

	base := int64(k)
	invBase := modPow(base, mod-2)
	invBaseSquared := invBase * invBase % mod

	power := modPow(base, w-1)
	var answer int64

	for d := 1; d <= k; d++ {
		dd := int64(d)
		fdSquared := fall[d] * fall[d] % mod

		var a int64
		if dd <= w {
			a = fdSquared * power % mod
		} else {
			overlap := int(dd - w)
			a = fdSquared * invFall[overlap] % mod
		}

		var b int64
		if d < k {
			r := d + 1
			frSquared := fall[r] * fall[r] % mod

			if w-dd-2 >= 0 {
				b = frSquared * power % mod
				b = b * invBaseSquared % mod
			} else {
				overlap := int(dd + 2 - w)
				b = frSquared * invFall[overlap] % mod
			}
		}

		answer += a - b
		answer %= mod
		if answer < 0 {
			answer += mod
		}

		power = power * invBase % mod
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}

