	"os"
)

const MOD int64 = 1000000007

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var k int
	var w int64
	fmt.Fscan(in, &k, &w)

	fact := make([]int64, k+1)
	invFact := make([]int64, k+1)

	fact[0] = 1
	for i := 1; i <= k; i++ {
		fact[i] = fact[i-1] * int64(i) % MOD
	}

	invFact[k] = modPow(fact[k], MOD-2)
	for i := k; i >= 1; i-- {
		invFact[i-1] = invFact[i] * int64(i) % MOD
	}

	permutation := func(n, r int) int64 {
		if r < 0 || r > n {
			return 0
		}
		return fact[n] * invFact[n-r] % MOD
	}

	sum := func(x int64) int64 {
		var result int64
		limit := k
		if x < int64(limit) {
			limit = int(x)
		}

		falling := int64(1)
		power := modPow(int64(k), x-1)
		invK := modPow(int64(k), MOD-2)

		for r := 1; r <= limit; r++ {
			falling = falling * int64(k-r+1) % MOD
			term := falling * falling % MOD
			term = term * power % MOD
			result += term
			if result >= MOD {
				result -= MOD
			}
			power = power * invK % MOD
		}

		if x < int64(k) {
			xi := int(x)
			for r := xi + 1; r <= k; r++ {
				t := r - xi
				a := permutation(k, t)
				b := permutation(k-t, xi)
				term := a * b % MOD * b % MOD
				result += term
				if result >= MOD {
					result -= MOD
				}
			}
		}

		return result
	}

	answer := (modPow(int64(k), w) + sum(w) - sum(w-1)) % MOD
	if answer < 0 {
		answer += MOD
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}

