	for i := 1; i <= k; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}
	invFact[k] = modPow(fact[k], mod-2)
	for i := k; i > 0; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	calculate := func(x int64) int64 {
		var result int64
		kk := int64(k)

		if k == 1 {
			result = x % mod
		} else {
			result = kk % mod
			result = result * ((modPow(kk, x)-1+mod)%mod) % mod
			result = result * modPow(kk-1, mod-2) % mod
		}

		limit := k
		if x < int64(limit) {
			limit = int(x)
		}

		power := modPow(kk, x-1)
		invK := modPow(kk, mod-2)

