			term := falling * falling % mod * power % mod
			result += term
			if result >= mod {
				result -= mod
			}
			power = power * invK % mod
		}

		if x < int64(k) {
			xi := int(x)
			for d := 1; d <= k-xi; d++ {
				n := k - d
				term := fact[k] * fact[n] % mod
				term = term * invFact[n-xi] % mod
				term = term * invFact[n-xi] % mod
				result += term
				if result >= mod {
					result -= mod
				}
			}
		}

		return result
	}

	answer := (calculate(w) - calculate(w-1) + mod) % mod

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
