package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1000000007

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var k, w int64
	fmt.Fscan(in, &k, &w)

	x := k % mod
	x2 := x * x % mod
	x3 := x2 * x % mod
	x4 := x3 * x % mod

	coef := (x4 - x3 + x2 - 2*x + 2) % mod
	if coef < 0 {
		coef += mod
	}

	answer := coef * modPow(x, w-2) % mod

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
